import{_ as e,c as l,o as n,a3 as r}from"./chunks/framework.BusRvirq.js";const h=JSON.parse('{"title":"사업 입찰 타당성 심의서 (Go / No-Go Evaluation Sheet)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/02_Go_NoGo_Evaluation_template.html"}]]},"headers":[],"relativePath":"public/templates/02_Go_NoGo_Evaluation_template.md","filePath":"public/templates/02_Go_NoGo_Evaluation_template.md","lastUpdated":1790810085000}'),s={name:"public/templates/02_Go_NoGo_Evaluation_template.md"};function a(o,t,i,d,g,x){return n(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="사업-입찰-타당성-심의서-go-no-go-evaluation-sheet" tabindex="-1">사업 입찰 타당성 심의서 (Go / No-Go Evaluation Sheet) <a class="header-anchor" href="#사업-입찰-타당성-심의서-go-no-go-evaluation-sheet" aria-label="Permalink to “사업 입찰 타당성 심의서 (Go / No-Go Evaluation Sheet)”">​</a></h1><p>본 문서는 제안 요청서(RFP) 분석 결과를 바탕으로 사업 입찰 참여 여부를 사전에 객관적으로 평가하고, 부실 수주 및 수행 적자 리스크를 차단하기 위해 작성하는 사내 공식 심의 문서입니다.</p><hr><h3 id="_1-사업-개요" tabindex="-1">1. 사업 개요 <a class="header-anchor" href="#_1-사업-개요" aria-label="Permalink to “1. 사업 개요”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명</strong></td><td style="text-align:left;">[발주처 공식 공고 사업명 입력]</td></tr><tr><td style="text-align:left;"><strong>발주 기관 / 고객사</strong></td><td style="text-align:left;">[발주처명] (유형: 공공 / 금융 / 민간 대기업 / 중소)</td></tr><tr><td style="text-align:left;"><strong>사업 예산 (추정가)</strong></td><td style="text-align:left;">일금 [ ] 원 (VAT 포함 / 별도)</td></tr><tr><td style="text-align:left;"><strong>수행 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일 (총 [ ] 개월)</td></tr><tr><td style="text-align:left;"><strong>제안서 제출 마감일</strong></td><td style="text-align:left;">202 년 월 일 [ ]:[ ] 마감</td></tr><tr><td style="text-align:left;"><strong>제안 발표(PT) 예정일</strong></td><td style="text-align:left;">202 년 월 일 (예정)</td></tr><tr><td style="text-align:left;"><strong>주관 영업 담당자</strong></td><td style="text-align:left;">[영업본부 직급 성명] (연락처: )</td></tr><tr><td style="text-align:left;"><strong>기술 검토 책임자 (TL)</strong></td><td style="text-align:left;">[기술본부 직급 성명] (연락처: )</td></tr></tbody></table><hr><h3 id="_2-7대-핵심-지표별-타당성-평가표" tabindex="-1">2. 7대 핵심 지표별 타당성 평가표 <a class="header-anchor" href="#_2-7대-핵심-지표별-타당성-평가표" aria-label="Permalink to “2. 7대 핵심 지표별 타당성 평가표”">​</a></h3><ul><li>평가 기준: 항목별 10점 만점 (배점 가중치 적용, 총점 100점 만점)</li><li>판정 기준: <strong>70점 이상 (Go - 입찰 추진)</strong> / <strong>60점 ~ 69점 (Conditional Go - 조건부 추진, 경영진 특인 필요)</strong> / <strong>60점 미만 (No-Go - 입찰 포기 원칙)</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th style="text-align:left;">평가 영역</th><th style="text-align:left;">핵심 점검 질문 및 위험 요인</th><th style="text-align:center;">배점</th><th style="text-align:center;">득점</th><th style="text-align:left;">주요 리스크 및 검토 의견</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;"><strong>기술 적합성</strong></td><td style="text-align:left;">당사 보유 코어 솔루션(SyncSeries/Verse) 및 기술 스택과 요구 기술이 80% 이상 부합하는가? 미보유 원천기술 개발 요구가 없는가?</td><td style="text-align:center;">15</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;"><strong>인프라 및 환경</strong></td><td style="text-align:left;">온프레미스 망분리, GPU 인프라, 클라우드 사양, OS 및 미들웨어 버전이 명확히 정의되어 있고 당사 아키텍처와 호환되는가?</td><td style="text-align:center;">15</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;"><strong>데이터 접근성</strong></td><td style="text-align:left;">AI 파인튜닝, RAG, 마이그레이션에 필요한 원천 데이터의 보안성, 결측률, 제공 시점이 사전에 보장되는가?</td><td style="text-align:center;">15</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;"><strong>일정 타당성</strong></td><td style="text-align:left;">과업 범위 대비 제안된 납기가 물리적으로 가능한가? 무리한 단축 납기나 사전 준비 없는 즉시 오픈 요구가 없는가?</td><td style="text-align:center;">15</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;"><strong>원가 및 수익성</strong></td><td style="text-align:left;">예정 가격 대비 당사 투입 원가(인건비, 외부 라이선스, 클라우드/GPU 장비비) 비율이 마진율 [ 25 ]% 이상을 확보할 수 있는가?</td><td style="text-align:center;">20</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;"><strong>수행 조직 가용성</strong></td><td style="text-align:left;">프로젝트 착수 시점에 즉시 투입 가능한 핵심 PM, PL, 아키텍트 등 정규직 전문 인력이 사내에 확보되어 있는가?</td><td style="text-align:center;">10</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:left;"><strong>보안 및 규제 제약</strong></td><td style="text-align:left;">금융감독원 망분리, 국정원 보안성 검토, ISMS-P 등 특수 규제 충족이 가능하며, 지체상금 조항(1일 0.075% 초과 등)이 과도하지 않은가?</td><td style="text-align:center;">10</td><td style="text-align:center;">[ ]</td><td style="text-align:left;">[검토 내용 기술]</td></tr><tr><td style="text-align:center;"><strong>합계</strong></td><td style="text-align:left;"><strong>총점</strong></td><td style="text-align:left;"><strong>가중치 합산 종합 점수</strong></td><td style="text-align:center;"><strong>100</strong></td><td style="text-align:center;"><strong>[ ]</strong></td><td style="text-align:left;"><strong>종합 점수: [ ] 점</strong></td></tr></tbody></table><hr><h3 id="_3-기술-총괄-tech-lead-서명-및-핵심-검토-의견" tabindex="-1">3. 기술 총괄(Tech Lead) 서명 및 핵심 검토 의견 <a class="header-anchor" href="#_3-기술-총괄-tech-lead-서명-및-핵심-검토-의견" aria-label="Permalink to “3. 기술 총괄(Tech Lead) 서명 및 핵심 검토 의견”">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">기술 책임자 사전 서명 의무화</p><p>제안서 제출 전, 기술 총괄은 RFP 요구사항 중 실현 불가능한 기술적 과장(기술 부채)이 없는지 확인하고 본 란에 직접 서명해야 합니다.</p></div><ol><li><strong>기술적 실현 가능성 (Feasibility)</strong>: [ 상 / 중 / 하 ]</li><li><strong>사전 PoC 필요 여부</strong>: [ 필요(소요 기간: 일) / 불필요 ]</li><li><strong>핵심 기술 위험 요인 및 완화 방안</strong>: <ul><li>위험 1: [ ]</li><li>대책 1: [ ]</li><li>위험 2: [ ]</li><li>대책 2: [ ]</li></ul></li></ol><ul><li><strong>기술 검토 책임자 (Tech Lead)</strong>: 직급: [ ] 성명: [ ] (서명)</li></ul><hr><h3 id="_4-영업-및-재무-원가-검토-의견" tabindex="-1">4. 영업 및 재무 원가 검토 의견 <a class="header-anchor" href="#_4-영업-및-재무-원가-검토-의견" aria-label="Permalink to “4. 영업 및 재무 원가 검토 의견”">​</a></h3><ol><li><strong>수주 경쟁 구도 및 당사 수주 확률</strong>: [ 높음(80% 이상) / 경합(50% 내외) / 낮음(30% 미만) ]</li><li><strong>주요 경쟁사</strong>: [ ]</li><li><strong>예상 공수 및 직접 원가</strong>: <ul><li>총 투입 공수: [ ] M/D (인월: [ ] M/M)</li><li>직접 인건비: 일금 [ ] 원</li><li>솔루션/라이선스 비용: 일금 [ ] 원</li><li>하드웨어 및 클라우드비: 일금 [ ] 원</li><li>예상 영업이익률: [ ] %</li></ul></li></ol><ul><li><strong>영업 검토 책임자 (Sales Lead)</strong>: 직급: [ ] 성명: [ ] (서명)</li></ul><hr><h3 id="_5-종합-판정-및-경영진-최종-결재" tabindex="-1">5. 종합 판정 및 경영진 최종 결재 <a class="header-anchor" href="#_5-종합-판정-및-경영진-최종-결재" aria-label="Permalink to “5. 종합 판정 및 경영진 최종 결재”">​</a></h3><ul><li><strong>최종 판정 결과</strong>: <ul><li>[ ] <strong>Go (수주 추진 승인)</strong>: 제안팀 공식 발족 및 제안서 작성 착수</li><li>[ ] <strong>Conditional Go (조건부 추진)</strong>: 아래 조건 충족 시에 한하여 추진 승인 <ul><li>부대 조건: [ ]</li></ul></li><li>[ ] <strong>No-Go (입찰 포기)</strong>: 공식 사유 통보 후 입찰 불참 처리</li></ul></li></ul><hr><p><strong>심의 일자: 202 년 월 일</strong></p><ul><li><strong>사업관리 총괄 (PMO Head)</strong>: 직급: [ ] 성명: [ ] (인)</li><li><strong>기술총괄임원 (CTO)</strong>: 직급: [ ] 성명: [ ] (인)</li><li><strong>대표이사 (CEO)</strong>: 직급: [ ] 성명: [ ] (인)</li></ul>',24)])])}const c=e(s,[["render",a]]);export{h as __pageData,c as default};
